previewCss:
.darma-loader-darma-b7-ripple-sonar { --accent: var(--loader-color, #22c55e); width: var(--loader-size, 72px); height: var(--loader-size, 72px); position: relative; }
.darma-loader-darma-b7-ripple-sonar span { position: absolute; inset: 0; border: calc(var(--loader-size, 72px) * .04) solid var(--accent); border-radius: 50%; opacity: 0; animation: darma-loader-darma-b7-ripple-sonar-sonar calc(var(--loader-speed, 1s) * 2) ease-out infinite; }
.darma-loader-darma-b7-ripple-sonar span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .66); }
.darma-loader-darma-b7-ripple-sonar span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.33); }
@keyframes darma-loader-darma-b7-ripple-sonar-sonar { 0% { transform: scale(.1); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }

